[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Customers must not bring carts into single-file aisles bounded by shelves, defined by local geometry rather than by fixed coordinates so the rule follows rearranged or rotated shelving.",
    "abstraction": {
      "state_properties": {
        "narrow_between_east_west_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrow_between_north_south_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "narrow_between_east_west_shelves",
            "narrow_between_north_south_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_shelf_aisle_on_foot",
    "text": "A shopper entering a single-file shelf aisle must do so without a cart, which generalizes because it refers to crossing into a locally constrained shelf aisle rather than to a particular aisle mouth.",
    "abstraction": {
      "state_properties": {
        "narrow_between_east_west_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrow_between_north_south_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "narrow_between_east_west_shelves",
            "narrow_between_north_south_shelves"
          ]
        }
      },
      "events": {
        "push_cart_into_single_file_shelf_aisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "single_file_shelf_aisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_into_single_file_shelf_aisle"
    }
