  {
    "id": "no_cart_shelf_service_in_single_file_aisle",
    "text": "Customers must not perform shelf interactions while holding a cart in a single-file shelf aisle, preserving access in any layout where the shelf area is locally too narrow for carts.",
    "abstraction": {
      "state_properties": {
        "narrow_between_east_west_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrow_between_north_south_shelves": {
