  {
    "id": "reclaim_cart_after_leaving_single_file_aisle",
    "text": "After leaving a single-file shelf aisle on foot, the shopper must reclaim the cart before finishing, which tracks the functional act of returning from a cart-restricted area rather than any observed coordinate.",
    "abstraction": {
      "state_properties": {
        "narrow_between_east_west_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrow_between_north_south_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "narrow_between_east_west_shelves",
            "narrow_between_north_south_shelves"
          ]
        },
        "outside_single_file_shelf_aisle": {
          "not": "single_file_shelf_aisle"
        }
      },
      "events": {
        "leave_single_file_shelf_aisle_on_foot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "single_file_shelf_aisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              "outside_single_file_shelf_aisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leave_single_file_shelf_aisle_on_foot",
      "discharge": "hasCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they must later retrieve a cart before exiting, which generalizes to the social duty not to abandon a cart after using it.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "park_cart_only_in_open_main_space",
    "text": "A cart may be parked only in a roomy open space away from shelves, not in a shelf-front or constricted aisle, so the rule depends on obstruction risk rather than store-specific parking coordinates.",
    "abstraction": {
      "state_properties": {
        "roomy_cell": {
          "or": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        },
        "open_cart_parking_area": {
          "and": [
            "roomy_cell",
            {
              "not": "adjShelf"
            }
          ]
        },
        "bad_cart_parking_area": {
          "not": "open_cart_parking_area"
        }
      },
      "events": {
        "park_cart_in_bad_area": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "bad_cart_parking_area"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "park_cart_in_bad_area"
    }
  },
  {
    "id": "exit_with_cart_after_taking_one",
    "text": "A shopper who takes or reclaims a store cart must eventually reach the exit while still with a cart, which avoids overfitting to shoppers who never used a cart at all.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquire_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "acquire_cart",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "use_cart_at_open_shelf_fronts",
    "text": "When interacting with a shelf from an open shelf frontage, the shopper should have the cart with them, while the exception for single-file shelf aisles is defined geometrically and can move with the layout.",
    "abstraction": {
      "state_properties": {
        "narrow_between_east_west_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrow_between_north_south_shelves": {
          "and": [
